        # Verificar rangos típicos meteorológicos
        range_checks = [
            'temperatura.*(-?\d+\.?\d*)',
            'humedad.*(\d+\.?\d*).*%',
            'precipitacion.*(\d+\.?\d*).*mm'
        ]

        print(f"\n   🔍 Verificación de rangos meteorológicos:")
